Str simse_http_errorText(const Str& step) {
    const unsigned long code = (unsigned long) ::GetLastError();
    Str text = step;
    text.append(" failed");
    if (code == 0) {
        text.append(": the library or its symbol could not be resolved");
        return text;
    }
    text.append(" (");
    text += std::to_string(code);
    text.append(")");
    char message[512];
    const unsigned long length = ::FormatMessageA(
        FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS,
        nullptr, code, 0, message, (unsigned long) sizeof(message), nullptr);
    if (length > 0) {
        unsigned long trimmed = length;
        while (trimmed > 0 && (message[trimmed - 1] == '\r' || message[trimmed - 1] == '\n')) {
            trimmed--;
        }
        text.append(": ");
        text.append(message, (Int) trimmed);
    }
    return text;
}

void simse_http_bufferInit(List<Char>* buffer, Int32 size) {
    buffer->resize(size);
}

void simse_http_append(List<Char>* out, const Char* bytes, Int32 count) {
    if (count <= 0) return;
    const Int base = out->size();
    out->resize(base + count);
    std::memcpy(out->data() + base, bytes, (std::size_t) count);
}

Str simse_http_charsToStr(const List<Char>* chars) {
    Str text;
    const Int count = chars->size();
    if (count <= 0) return text;
    text.resize(count);
    std::memcpy(text.data(), chars->data(), (std::size_t) count);
    return text;
}


FileStream* simse_fileStream_open(const Str& path) {
    auto* stream = new FileStream();
    stream->file.open(simse_toStdString(path), std::ios::binary);
    if (!stream->file.is_open()) {
        delete stream;
        return nullptr;
    }
    stream->chunk.resize(256 * 1024);
    std::error_code ec;
    const std::uintmax_t size = std::filesystem::file_size(simse_toStdString(path), ec);
    stream->size = ec ? 0 : (Int64) size;
    return stream;
}

Opt<Str> FileStream::readLine() {
    if (!std::getline(file, line)) {
        return Opt<Str>();
    }
    if (!line.empty() && line.back() == '\r') {
        line.pop_back();
    }
    Opt<Str> result;
    result.setValue(simse_fromStdString(line));
    return result;
}

Bool FileStream::readLineInto(Str* buffer) {
    if (buffer == nullptr) return false;
    Int from = 0;
    Int count = 0;
    if (!nextLineSpan(&from, &count)) return false;
    take(buffer, chunk.data() + from, count);
    return true;
}

Opt<StrView> FileStream::readLineView() {
    Int from = 0;
    Int count = 0;
    if (!nextLineSpan(&from, &count)) return Opt<StrView>();
    Char* base = const_cast<Char*>(reinterpret_cast<const Char*>(chunk.data()));
    Opt<StrView> result;
    result.setValue(StrView(base + from, count));
    return result;
}

Int64 FileStream::fileSize() const {
    return size;
}

void FileStream::close() {
    file.close();
    delete this;
}

Bool FileStream::nextLineSpan(Int* from, Int* count) {
    Int at = chunkAt;
    while (true) {
        const Int limit = chunkLen;
        if (at < limit) {
            const char* base = chunk.data();
            const void* found = std::memchr(base + at, '\n', (std::size_t) (limit - at));
            if (found != nullptr) {
                const Int end = (Int) ((const char*) found - base);
                Int len = end - at;
                if (len > 0 && base[end - 1] == '\r') len--;
                *from = at;
                *count = len;
                chunkAt = end + 1;
                return true;
            }
        }
        Int tail = limit - at;
        if (tail > 0 && at > 0) {
            std::memmove(chunk.data(), chunk.data() + at, (std::size_t) tail);
        }
        if (tail == chunk.size()) {
            chunk.resize(tail * 2);
        }
        file.read(chunk.data() + tail, (std::streamsize) (chunk.size() - tail));
        const std::streamsize got = file.gcount();
        if (got <= 0) {
            chunkLen = 0;
            chunkAt = 0;
            if (tail == 0) return false;
            Int len = tail;
            if (len > 0 && chunk[len - 1] == '\r') len--;
            *from = 0;
            *count = len;
            return true;
        }
        chunkLen = tail + (Int) got;
        chunkAt = 0;
        at = 0;
    }
}

void FileStream::take(Str* buffer, const char* text, Int count) {
    buffer->resize(count);
    if (count > 0) std::memcpy(buffer->data(), text, (std::size_t) count);
}

inline Str simse_resHexToBytes(const Str& self) {
    Str out;
    out.reserve(self.size() / 2);
    Int high = -1;
    for (Char ch : self) {
        if (ch == ' ' || ch == '\t' || ch == '\n' || ch == '\r') continue;
        Int digit = -1;
        if (ch >= '0' && ch <= '9') digit = ch - '0';
        else if (ch >= 'a' && ch <= 'f') digit = ch - 'a' + 10;
        if (digit < 0) break;
        if (high < 0) {
            high = digit;
        } else {
            out.push_back((char) (high * 16 + digit));
            high = -1;
        }
    }
    return out;
}

inline Str simse_resQuoteBinary(const Str& self) {
    Str out = "\"";
    for (Char ch : self) {
        Int byte = (Int) (unsigned char) ch;
        if (ch == '\\') {
            out.append("\\\\");
        } else if (ch == '\"') {
            out.append("\\\"");
        } else if (byte >= 0x20 && byte <= 0x7e) {
            out.push_back((char) byte);
        } else {
            out.push_back('\\');
            out.push_back((char) ('0' + ((byte >> 6) & 7)));
            out.push_back((char) ('0' + ((byte >> 3) & 7)));
            out.push_back((char) ('0' + (byte & 7)));
        }
    }
    out.push_back('"');
    return out;
}

template <class T>
inline void simse_strTableExpand(const T* stream, Int* out, Int count) {
    Int at = 0;
    Int cursor = 1; 
    while (at < count) {
        const Int literals = (Int) stream[cursor++];
        for (Int i = 0; i < literals && at < count; i++) out[at++] = (Int) stream[cursor++];
        if (at >= count) break;
        const Int runs = (Int) stream[cursor++];
        for (Int i = 0; i < runs && at < count; i++) {
            const Int times = (Int) stream[cursor++];
            const Int value = (Int) stream[cursor++];
            for (Int j = 0; j < times && at < count; j++) out[at++] = value;
        }
    }
}

inline void simse_strTableDecode(const char* pool, const Int* starts, const Int* lengths, StrView* table, Int count) {
    Char* bytes = const_cast<Char*>(reinterpret_cast<const Char*>(pool));
    Int delta = 0;  
    Int length = 0; 
    Int at = 0;
    for (Int i = 0; i < count; i++) {
        delta -= starts[i];
        length -= lengths[i];
        at += delta;
        table[i] = StrView(bytes + at, length);
    }
}

Int64 simse_nowMillis() {
    const auto now = std::chrono::steady_clock::now().time_since_epoch();
    return (Int64) std::chrono::duration_cast<std::chrono::milliseconds>(now).count();
}

Int64 simse_nowMicros() {
    const auto now = std::chrono::steady_clock::now().time_since_epoch();
    return (Int64) std::chrono::duration_cast<std::chrono::microseconds>(now).count();
}

Int64 simse_nowNanos() {
    const auto now = std::chrono::steady_clock::now().time_since_epoch();
    return (Int64) std::chrono::duration_cast<std::chrono::nanoseconds>(now).count();
}

